-- Voicemail boxes: one per extension plus "main" (src/voicemail.ts). Replaces
-- the single shared greeting library, whose settings now live in Odoo.
CREATE TABLE IF NOT EXISTS voicemail_boxes (
  box TEXT PRIMARY KEY,           -- "main" or an extension number
  enabled INTEGER NOT NULL DEFAULT 1,
  greeting BLOB,                  -- 8 kHz mono 16-bit WAV, NULL = the stock prompt
  greeting_version INTEGER,       -- changes whenever the greeting does
  duration_ms INTEGER,
  updated_at INTEGER NOT NULL
);
DROP TABLE IF EXISTS greetings;
-- Which box a voicemail was left in (NULL = not a voicemail, or before boxes).
ALTER TABLE call_log ADD COLUMN voicemail_box TEXT;
